  G.tn = (o) => (o ? o[G.LANG] || o.ru : '');
  G.t = function (key, p) {
    let s = G.STR[G.LANG][key];
    if (s === undefined) s = G.STR.ru[key];
    if (s === undefined) return key;
    if (p) s = s.replace(/\{(\w+)\}/g, (m, k) => (p[k] !== undefined ? p[k] : m));
    return s;
  };
